package blockbranch.realistic;
import java.nio.file.*;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.levelgen.structure.*;
import net.minecraft.world.level.levelgen.structure.pieces.StructurePieceSerializationContext;
/** Read-only current-main native mansion and inherited compound anatomy. */
public final class MansionReplacementExport {
 private static final com.google.gson.Gson JSON=new com.google.gson.GsonBuilder().setPrettyPrinting().create(),COMPACT=new com.google.gson.Gson();
 public static void write(ServerLevel level,ReimaginedMansionPiece marker,StructureStart start,Path dir,boolean reopen)throws Exception {
  String prefix=reopen?"reopen-":"";var ctx=StructurePieceSerializationContext.fromLevel(level);var tag=marker.createTag(ctx);int[] c=tag.getIntArray("Core").orElseThrow();var core=new BoundingBox(c[0],c[1],c[2],c[3],c[4],c[5]);var box=marker.getBoundingBox();var bes=new ArrayList<Object>();var lamps=new ArrayList<Object>();var palette=new TreeMap<String,Integer>();int count=0,nativeCount=0;
  try(var out=Files.newBufferedWriter(dir.resolve(prefix+"mansion-site.voxels.jsonl"));var nativeOut=Files.newBufferedWriter(dir.resolve(prefix+"native-core.voxels.jsonl"))){
   for(int y=box.minY();y<=box.maxY();y++)for(int z=box.minZ();z<=box.maxZ();z++)for(int x=box.minX();x<=box.maxX();x++){
    var at=new BlockPos(x,y,z);var s=level.getBlockState(at);boolean inside=core.isInside(at);var row=Map.of("x",x,"y",y,"z",z,"state",s.toString(),"collision",s.getCollisionShape(level,at).toAabbs().toString(),"fluid",net.minecraft.core.registries.BuiltInRegistries.FLUID.getKey(s.getFluidState().getType())+"/"+s.getFluidState().getAmount(),"blockLight",level.getBrightness(net.minecraft.world.level.LightLayer.BLOCK,at),"skyLight",level.getBrightness(net.minecraft.world.level.LightLayer.SKY,at));String line=COMPACT.toJson(row)+"\n";out.write(line);count++;if(inside){nativeOut.write(line);nativeCount++;palette.merge(s.toString(),1,Integer::sum);}
    var be=level.getBlockEntity(at);if(be!=null)bes.add(Map.of("world",List.of(x,y,z),"nativeCore",inside,"state",s.toString(),"type",be.getClass().getSimpleName(),"fullNBT",be.saveWithFullMetadata(level.registryAccess()).toString()));
    if(s.getLightEmission()>0)lamps.add(Map.of("world",List.of(x,y,z),"state",s.toString(),"emission",s.getLightEmission(),"nativeCore",inside));
   }
  }
  var terrain=new ArrayList<Object>();var g=(RealisticGenerator)level.getChunkSource().getGenerator();var drainage=g.hutPlanningTerrain(level.getChunkSource().randomState()).drainage();
  for(int z=box.minZ();z<=box.maxZ();z++)for(int x=box.minX();x<=box.maxX();x++){var p=new BlockPos(x,box.minY()-1,z);var s=level.getBlockState(p);terrain.add(Map.of("x",x,"z",z,"originalPlannedSurface",drainage.sample(x,z).height(),"belowCompoundY",p.getY(),"belowCompoundState",s.toString(),"belowCompoundFullUpperSupport",s.isFaceSturdy(level,p,net.minecraft.core.Direction.UP)));}
  var pieces=new ArrayList<Object>();for(var p:start.getPieces()){var b=p.getBoundingBox();String name=p instanceof net.minecraft.world.level.levelgen.structure.structures.WoodlandMansionPieces.WoodlandMansionPiece?((blockbranch.mixin.cubic.ReimaginedTemplateName)p).blockbranch$reimaginedTemplate():p.getClass().getSimpleName();pieces.add(Map.of("class",p.getClass().getSimpleName(),"template",name,"bounds",List.of(b.minX(),b.minY(),b.minZ(),b.maxX(),b.maxY(),b.maxZ()),"fullNBT",p.createTag(ctx).toString()));}
  Files.writeString(dir.resolve(prefix+"native-block-entities.json"),JSON.toJson(bes));Files.writeString(dir.resolve(prefix+"native-light-sources.json"),JSON.toJson(lamps));Files.writeString(dir.resolve(prefix+"native-piece-anatomy.json"),JSON.toJson(pieces));Files.writeString(dir.resolve(prefix+"terrain-support-context.json"),JSON.toJson(terrain));Files.writeString(dir.resolve(prefix+"native-anatomy.json"),JSON.toJson(Map.of("source","Actual native mansion stage export; pristine and player-edited stages explicitly distinguished","markerBounds",List.of(box.minX(),box.minY(),box.minZ(),box.maxX(),box.maxY(),box.maxZ()),"nativeCoreBounds",List.of(c[0],c[1],c[2],c[3],c[4],c[5]),"floor",tag.getIntOr("Floor",0),"siteVoxels",count,"nativeVoxels",nativeCount,"nativePalette",palette,"blockEntities",bes.size(),"pieces",pieces.size())));
 }
 public static Map<String,Object> qualification(ServerLevel level,ReimaginedMansionPiece marker,Path dir,boolean reopen)throws Exception {
  // ReimaginedRoutes.servicePassage performs player interactions and is deliberately not used here.
  var tag=marker.createTag(StructurePieceSerializationContext.fromLevel(level));int[] ends=tag.getIntArray("Passage").orElseThrow();var hatches=Set.of(new BlockPos(ends[0],ends[1]-1,ends[2]),new BlockPos(ends[3],ends[4]-1,ends[5]));
  for(var p:hatches)if(!level.getBlockState(p).is(net.minecraft.world.level.block.Blocks.OAK_TRAPDOOR))throw new AssertionError("Original service hatch exists");
  var seen=new HashSet<BlockPos>();var queue=new ArrayDeque<BlockPos>();var first=new BlockPos(ends[0],ends[1],ends[2]);var goal=new BlockPos(ends[3],ends[4],ends[5]);seen.add(first);queue.add(first);
  while(!queue.isEmpty()){var p=queue.removeFirst();for(var direction:net.minecraft.core.Direction.values()){var n=p.relative(direction);if(!marker.getBoundingBox().isInside(n)||seen.contains(n)||!virtualClear(level,n,hatches)||!virtualClear(level,n.above(),hatches))continue;boolean climb=climb(level,p,hatches)||climb(level,n,hatches);if(direction.getAxis().isVertical()&&!climb||virtualClear(level,n.below(),hatches)&&!climb)continue;seen.add(n);queue.add(n);}}
  if(!seen.contains(goal))throw new AssertionError("Service corridor/ladders connected with virtual hatch opening only");
  var bes=COMPACT.fromJson(Files.readString(dir.resolve((reopen?"reopen-":"")+"native-block-entities.json")),com.google.gson.JsonArray.class);var actual=new TreeMap<String,String>();var expected=new TreeMap<String,String>();int chests=0;
  for(var value:bes){var row=value.getAsJsonObject();var a=row.getAsJsonArray("world");var at=new BlockPos(a.get(0).getAsInt(),a.get(1).getAsInt(),a.get(2).getAsInt());var be=level.getBlockEntity(at);if(be==null)throw new AssertionError("Original native BE survives inspection "+at);var old=net.minecraft.nbt.TagParser.parseCompoundFully(row.get("fullNBT").getAsString());var now=be.saveWithFullMetadata(level.registryAccess());if(be instanceof net.minecraft.world.level.block.entity.SpawnerBlockEntity){old.remove("Delay");now.remove("Delay");}if(be instanceof net.minecraft.world.level.block.entity.ChestBlockEntity)chests++;expected.put(at.toShortString(),old.toString());actual.put(at.toShortString(),now.toString());}
  if(!actual.equals(expected))throw new AssertionError("Read-only inspection preserves all native BE/config/loot seeds except volatile spawner Delay");
  Files.writeString(dir.resolve((reopen?"reopen-":"")+"final-block-entity-witness.json"),JSON.toJson(actual));
  return Map.of("nativeChests",chests,"allNativeAndCompoundBlockEntities",actual.size(),"allBEConfigAndLootSeedsUnchanged",true,"spawnerDelayOnlyVolatile",true,"compoundRouteCells",0,"virtualServiceRouteCells",seen.size(),"serviceHatchesNeverInteractedWith",true,"noWorldInventoryOrNpcWrites",true);
 }
 // Vanilla lazily serializes modifier-free default attributes after AI first accesses them.
 // Keep every nondefault base and every modifier; Allay NoGravity belongs to FlyingMoveControl state.
 public static net.minecraft.nbt.CompoundTag stableResident(net.minecraft.nbt.CompoundTag tag,String type){
  var stable=tag.copy();if(type.equals("minecraft:allay"))stable.remove("NoGravity");
  var defaults=switch(type){case "minecraft:evoker"->net.minecraft.world.entity.ai.attributes.DefaultAttributes.getSupplier(net.minecraft.world.entity.EntityTypes.EVOKER);case "minecraft:vindicator"->net.minecraft.world.entity.ai.attributes.DefaultAttributes.getSupplier(net.minecraft.world.entity.EntityTypes.VINDICATOR);case "minecraft:allay"->net.minecraft.world.entity.ai.attributes.DefaultAttributes.getSupplier(net.minecraft.world.entity.EntityTypes.ALLAY);default->throw new AssertionError("Native resident type");};
  var attributes=stable.getListOrEmpty("attributes");for(int i=attributes.size()-1;i>=0;i--){var row=attributes.getCompoundOrEmpty(i);var attribute=switch(row.getStringOr("id","")){case "minecraft:movement_speed"->net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED;case "minecraft:attack_damage"->net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE;default->null;};if(attribute!=null&&row.keySet().size()==2&&row.contains("base")&&defaults.hasAttribute(attribute)&&Double.compare(row.getDoubleOr("base",Double.NaN),defaults.getBaseValue(attribute))==0)attributes.remove(i);}return stable;
 }
 private static boolean virtualClear(ServerLevel level,BlockPos p,Set<BlockPos> hatches){return hatches.contains(p)||level.getBlockState(p).is(net.minecraft.world.level.block.Blocks.LADDER)||level.getBlockState(p).getCollisionShape(level,p).isEmpty();}
 private static boolean climb(ServerLevel level,BlockPos p,Set<BlockPos> hatches){for(var at:List.of(p,p.below(),p.above()))if(hatches.contains(at)||level.getBlockState(at).is(net.minecraft.world.level.block.Blocks.LADDER))return true;return false;}
 public static void residents(ServerLevel level,ReimaginedMansionPiece marker,Path dir,boolean reopen)throws Exception {
  var mobs=level.getEntitiesOfClass(net.minecraft.world.entity.Mob.class,new net.minecraft.world.phys.AABB(marker.getBoundingBox().minX(),marker.getBoundingBox().minY(),marker.getBoundingBox().minZ(),marker.getBoundingBox().maxX()+1,marker.getBoundingBox().maxY()+1,marker.getBoundingBox().maxZ()+1).inflate(64));var out=new ArrayList<Object>();var counts=new TreeMap<String,Integer>();
  for(var e:mobs){String type=net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getKey(e.getType()).toString();if(!Set.of("minecraft:evoker","minecraft:vindicator","minecraft:allay").contains(type))continue;var n=net.minecraft.world.level.storage.TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,level.registryAccess());e.save(n);var full=n.buildResult();var stable=full.copy();for(String key:List.of("Pos","Motion","Rotation","OnGround","fall_distance","FallDistance","Brain","listener","current_impulse_context_reset_grace_time","Air","Fire","PortalCooldown","AbsorptionAmount","HurtTime","DeathTime","Health","FallFlying","SpellTicks"))stable.remove(key);out.add(Map.of("uuid",e.getUUID().toString(),"type",type,"position",List.of(e.getX(),e.getY(),e.getZ()),"fullNBT",full.toString(),"stableConfigurationNBT",stable.toString(),"observedHealth",e.getHealth()));counts.merge(type,1,Integer::sum);}
  if(out.isEmpty())throw new AssertionError("Actual native occupied mansion residents");Files.writeString(dir.resolve((reopen?"reopen-":"")+"native-residents.json"),JSON.toJson(Map.of("counts",counts,"residents",out)));var p=level.getServer().getPlayerList().getPlayers().getFirst();Files.writeString(dir.resolve((reopen?"reopen-":"")+"pristine-player.json"),JSON.toJson(Map.of("uuid",p.getUUID().toString(),"inventoryEmpty",p.getInventory().isEmpty())));
 }
}
